/// <summary>
/// Parameter data contract for importing files from Azure file shares including its subdirectories
/// </summary>
[DataContract]
class OMGInboundDataContract_AzureFileShareSubDir extends OMGInboundDataContract_AzureFileShare
{    
    OMGArchiveUnderSubDir       archiveUnderSourceDirectory;
    OMGAzureArchiveFolderName   archiveFolderName;

}

Method.Source:
[DataMember, SysOperationDisplayOrder('10'), OMGArchiveUnderSubDir]
public OMGArchiveUnderSubDir parmArchiveUnderSourceDirectory(OMGArchiveUnderSubDir _archiveUnderSourceDirectory = archiveUnderSourceDirectory)
{
    archiveUnderSourceDirectory = _archiveUnderSourceDirectory;
    return archiveUnderSourceDirectory;
}

[DataMember, OMGAzureArchiveContainerName, SysOperationDisplayOrder('11')]
public OMGAzureArchiveFolderName parmArchiveFolderName(OMGAzureArchiveFolderName _archiveFolderName = archiveFolderName)
{
    archiveFolderName = _archiveFolderName;
    return archiveFolderName;
}

/// <summary>
/// The caption used on the dialog
/// </summary>
/// <returns>A descriptive text</returns>
public Description dialogCaption()
{
    return "@OMG:ImportFromAzureFileShareSubDir";
}
